#!/bin/bash
set -e

echo "=================================================="
echo " Deploy: Side-by-side Examination Findings layout"
echo " on the OPD Case Sheet printout"
echo "=================================================="
echo ""
echo "Examination Findings used to stack 5 full-width"
echo "sections (External, Anterior, Posterior, Applanation,"
echo "Gonioscopy) one after another -- lots of repeated"
echo "headers and wasted width on paper."
echo ""
echo "Now paired side by side, each pair sharing one row:"
echo "  Row 1: External Examination | Anterior Segment"
echo "  Row 2: Posterior Segment    | Applanation Tonometry"
echo "  Row 3: Gonioscopy (full width -- less common, no"
echo "         natural pair)"
echo ""
echo "A row only renders if at least one side has data. If"
echo "only one side of a pair has data, the other side shows"
echo "a small \"not recorded\" note instead of empty space, so"
echo "the row always uses the full width."
echo ""

TARGET="app/print-templates/actions.js"

if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi

echo "Backing up current file to $TARGET.bak ..."
cp "$TARGET" "$TARGET.bak"

echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"

echo ""
echo "Verifying JS syntax ..."
node --check "$TARGET" && echo "  Syntax OK"

echo ""
echo "Done. Review the diff with:"
echo "  git diff $TARGET"
echo ""
echo "NOTE: If the OPD Case Sheet template has ever been"
echo "customized via the in-app Print Templates editor, that"
echo "saved version overrides this code default. To pick up"
echo "this layout, reset it from that admin page on BOTH"
echo "production and training, or run:"
echo "  delete from print_templates where template_key = $'opd_case_sheet$';"
echo "on both Supabase projects."
